#include "bundle.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <wchar.h>
#include <windows.h>

#include "bundle_files.h" // generated by gen_bundle.py
#include "util/log.h"
#include "util/str.h"

#define BUNDLE_COUNT (sizeof(sc_bundle_files) / sizeof(*sc_bundle_files))

static bool
set_env_if_unset(const wchar_t *name, const wchar_t *value) {
    if (_wgetenv(name)) {
        return true;
    }
    return _wputenv_s(name, value) == 0;
}

// Create the directory and its parents
static bool
create_dirs(wchar_t *path) {
    for (wchar_t *p = path + 3; *p; ++p) { // skip "C:\"
        if (*p == L'\\') {
            *p = L'\0';
            CreateDirectoryW(path, NULL);
            *p = L'\\';
        }
    }
    return CreateDirectoryW(path, NULL)
        || GetLastError() == ERROR_ALREADY_EXISTS;
}

static bool
file_has_size(const wchar_t *path, unsigned long long size) {
    WIN32_FILE_ATTRIBUTE_DATA attrs;
    if (!GetFileAttributesExW(path, GetFileExInfoStandard, &attrs)) {
        return false;
    }
    unsigned long long actual =
        ((unsigned long long) attrs.nFileSizeHigh << 32) | attrs.nFileSizeLow;
    return actual == size;
}

static bool
extract_file(const struct sc_bundle_file *file, const wchar_t *dir) {
    wchar_t *name = sc_str_to_wchars(file->name);
    if (!name) {
        return false;
    }
    wchar_t path[MAX_PATH];
    wchar_t tmp[MAX_PATH];
    int n1 = _snwprintf(path, MAX_PATH, L"%ls\\%ls", dir, name);
    int n2 = _snwprintf(tmp, MAX_PATH, L"%ls\\%ls.%lu.tmp", dir, name,
                        GetCurrentProcessId());
    free(name);
    if (n1 < 0 || n1 >= MAX_PATH || n2 < 0 || n2 >= MAX_PATH) {
        return false;
    }

    if (file_has_size(path, file->size)) {
        // Already extracted (the directory is versioned by content hash)
        return true;
    }

    HRSRC res = FindResourceW(NULL, MAKEINTRESOURCEW(file->id),
                              MAKEINTRESOURCEW(10)); // RT_RCDATA
    HGLOBAL handle = res ? LoadResource(NULL, res) : NULL;
    const void *data = handle ? LockResource(handle) : NULL;
    DWORD size = res ? SizeofResource(NULL, res) : 0;
    if (!data || size != file->size) {
        LOGE("Bundled resource not found: %s", file->name);
        return false;
    }

    // Write to a temporary file then rename, so that a concurrent launch
    // never sees a partial file
    HANDLE f = CreateFileW(tmp, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS,
                           FILE_ATTRIBUTE_NORMAL, NULL);
    if (f == INVALID_HANDLE_VALUE) {
        return false;
    }
    DWORD written = 0;
    BOOL ok = WriteFile(f, data, size, &written, NULL) && written == size;
    CloseHandle(f);
    if (!ok) {
        DeleteFileW(tmp);
        return false;
    }

    if (!MoveFileExW(tmp, path, MOVEFILE_REPLACE_EXISTING)) {
        DeleteFileW(tmp);
        // Another instance may have extracted it meanwhile (and may be
        // running it, so it cannot be replaced)
        return file_has_size(path, file->size);
    }
    return true;
}

bool
sc_bundle_init(void) {
    const wchar_t *local = _wgetenv(L"LOCALAPPDATA");
    if (!local) {
        LOGE("LOCALAPPDATA is not set, cannot extract the bundled files");
        return false;
    }

    wchar_t dir[MAX_PATH];
    int n = _snwprintf(dir, MAX_PATH, L"%ls\\scrcpy-gui\\runtime\\%hs",
                       local, SC_BUNDLE_HASH);
    if (n < 0 || n >= MAX_PATH - 64) {
        return false;
    }
    if (!create_dirs(dir)) {
        LOGE("Could not create the runtime directory");
        return false;
    }

    for (size_t i = 0; i < BUNDLE_COUNT; ++i) {
        if (!extract_file(&sc_bundle_files[i], dir)) {
            LOGE("Could not extract %s", sc_bundle_files[i].name);
            return false;
        }
    }

    wchar_t value[MAX_PATH];
    _snwprintf(value, MAX_PATH, L"%ls\\scrcpy-server", dir);
    set_env_if_unset(L"SCRCPY_SERVER_PATH", value);
    set_env_if_unset(L"SCRCPY_ICON_DIR", dir);
    _snwprintf(value, MAX_PATH, L"%ls\\adb.exe", dir);
    _wputenv_s(L"SCRCPY_GUI_BUNDLED_ADB", value);
    return true;
}
